$:set -euo pipefail
gh auth setup-git
git fetch origin +refs/heads/main:refs/remotes/origin/main
git checkout -B issue10-number-gates-20261103 origin/main
node <<'NODE'
"use strict";
const fs=require("node:fs");
const replacements=[
  [".github/workflows/issue-10-runtimeconfig.yml","github.event.issue.number == 10 &&\n          ",""],
  ["workspaces/RuntimeConfig/prepare-runtrigger.js","id <= 0 || number !== 10","id <= 0"]
];
for(const [file,oldValue,newValue] of replacements){
  const src=fs.readFileSync(file,"utf8");
  if(src.split(oldValue).length!==2)throw Error("Expected one occurrence of Issue number condition in "+file);
  fs.writeFileSync(file,src.replace(oldValue,newValue));
  console.log(JSON.stringify({changed:file,exactly_one_gate_removed:true}));
}
NODE
node --check workspaces/RuntimeConfig/prepare-runtrigger.js
git diff --check
git config user.name 'github-actions[bot]'
git config user.email '41898282+github-actions[bot]@users.noreply.github.com'
git add -- .github/workflows/issue-10-runtimeconfig.yml workspaces/RuntimeConfig/prepare-runtrigger.js
git diff --cached -- .github/workflows/issue-10-runtimeconfig.yml workspaces/RuntimeConfig/prepare-runtrigger.js
git commit -m "Remove hardcoded Issue 10 number gates"
git push origin HEAD:main
git rev-parse HEAD
